create function private.care_planning_person(person_id text,city text,staff_role text default null) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from private.care_planning s,jsonb_array_elements(s.snapshot->'directory') p
 where p->>'id'=person_id and p->>'city'=city and (staff_role is null or p->>'role'=staff_role))
$$;
revoke all on function private.care_planning_person(text,text,text) from public,anon,authenticated;

create function private.care_operations_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare p jsonb; prior jsonb; baseline jsonb; assignment jsonb; current_assignment jsonb; counts jsonb; expected jsonb;
 city text; city_key text; case_id text; revision integer; previous_revision integer; staff_id text; count_value jsonb; sid text;
begin
 if tg_op<>'INSERT' then
  if old.kind in ('care_assignment','care_followup') then raise insufficient_privilege using message='Care operations history is append-only';end if;
  return case when tg_op='DELETE' then old else new end;
 end if;
 if new.kind not in ('care_assignment','care_followup') then return new;end if;
 if auth.uid() is null or not private.care_has(new.senior_id,array['coordinator']) then raise insufficient_privilege;end if;
 p:=new.payload;
 if p->>'actor' is distinct from auth.uid()::text then raise insufficient_privilege using message='Care actor must be the verified caller';end if;
 if coalesce(p->>'revision','')!~'^[1-9][0-9]{0,8}$' then raise invalid_parameter_value using message='Invalid care revision';end if;
 revision:=(p->>'revision')::integer;
 select a into baseline from private.care_planning s,jsonb_array_elements(s.snapshot->'assignments') a where a->>'seniorId'=new.senior_id;
 if baseline is null then raise invalid_parameter_value using message='Senior is absent from the fictional planning roster';end if;
 city:=baseline->>'city';
 if new.kind='care_assignment' then
  if not private.care_admin() or not exists(select 1 from public.care_memberships m where m.user_id=auth.uid()::text and m.workspace_id='primary' and m.role='coordinator' and m.status='active' and m.scope_json::jsonb ? '*') then raise insufficient_privilege using message='Assignment management requires full-scope administrator access';end if;
  assignment:=p->'assignment';
  if assignment->>'seniorId' is distinct from new.senior_id or assignment->>'householdId' is distinct from new.senior_id or assignment->>'city' is distinct from city or assignment->>'source' is distinct from 'recorded'
   or not private.care_planning_person(assignment->>'counsellorId',city,'counsellor') or not private.care_planning_person(assignment->>'leaderId',city,'leader') or not private.care_planning_person(assignment->>'backupId',city,'counsellor') or assignment->>'counsellorId'=assignment->>'backupId'
  then raise invalid_parameter_value using message='Invalid planning assignment';end if;
  -- Current cities contain ASCII letters and spaces; match encodeURIComponent.
  city_key:=replace(city,' ','%20');
  perform pg_advisory_xact_lock(hashtextextended(new.owner||':care-city:'||city,0));
  if p->>'entryType'='request' then
   if new.id!~('^care-assignment-request:'||auth.uid()::text||':[a-fA-F0-9-]{36}$') or not exists(select 1 from public.care_events e where e.owner=new.owner and e.kind='care_assignment' and e.senior_id=new.senior_id and e.payload->>'entryType'='assignment' and e.payload->>'actor'=auth.uid()::text and e.payload->'revision'=p->'revision' and e.payload->'assignment'=assignment) then raise invalid_parameter_value using message='Assignment receipt has no matching committed assignment';end if;
   return new;
  end if;
  if p->>'entryType' is distinct from 'assignment' or p->>'city' is distinct from city or new.id is distinct from 'care-assignment-city:'||city_key||':'||revision::text then raise invalid_parameter_value;end if;
  select e.payload into prior from public.care_events e where e.owner=new.owner and e.kind='care_assignment' and e.payload->>'entryType'='assignment' and e.payload->>'city'=city order by (e.payload->>'revision')::integer desc limit 1;
  previous_revision:=coalesce((prior->>'revision')::integer,0);
  if revision<>previous_revision+1 then raise unique_violation using message='City assignment revision changed';end if;
  if prior is null then
   select jsonb_object_agg(person->>'id',to_jsonb((select count(*) from private.care_planning s2,jsonb_array_elements(s2.snapshot->'assignments') a where a->>'counsellorId'=person->>'id'))) into counts
    from private.care_planning s,jsonb_array_elements(s.snapshot->'directory') person where person->>'city'=city and person->>'role'='counsellor';
  else counts:=prior->'capacityCounts';end if;
  select e.payload->'assignment' into current_assignment from public.care_events e where e.owner=new.owner and e.kind='care_assignment' and e.senior_id=new.senior_id and e.payload->>'entryType'='assignment' order by (e.payload->>'revision')::integer desc limit 1;
  current_assignment:=coalesce(current_assignment,baseline);expected:=counts;
  if current_assignment->>'counsellorId'<>assignment->>'counsellorId' then
   staff_id:=current_assignment->>'counsellorId';expected:=jsonb_set(expected,array[staff_id],to_jsonb((expected->>staff_id)::integer-1));
   staff_id:=assignment->>'counsellorId';expected:=jsonb_set(expected,array[staff_id],to_jsonb((expected->>staff_id)::integer+1));
  end if;
  if p->'capacityCounts' is distinct from expected then raise invalid_parameter_value using message='Planning capacity must match the saved city ledger';end if;
  for count_value in select value from jsonb_each(expected) loop
   if jsonb_typeof(count_value)<>'number' or count_value::text!~'^[0-2]$' then raise invalid_parameter_value using message='A counsellor can own at most two fictional households';end if;
  end loop;
  return new;
 end if;
 case_id:=p->>'caseId';
 if coalesce(case_id,'')!~'^[a-fA-F0-9]{8}-([a-fA-F0-9]{4}-){3}[a-fA-F0-9]{12}$' or p->>'seniorId' is distinct from new.senior_id or p->'externalDelivery' is distinct from 'false'::jsonb then raise invalid_parameter_value;end if;
 if new.id is distinct from 'care-case:'||case_id||':'||revision::text or not private.care_planning_person(p->>'assignedTo',city) then raise invalid_parameter_value;end if;
 if coalesce(length(btrim(p->>'action')),0) not between 10 and 1600 or coalesce(length(btrim(p->>'note')),0) not between 10 and 1600 or coalesce(p->>'category','') not in ('wellbeing','clinical_review','companionship','home_safety','daily_assistance') then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.owner||':care-case:'||case_id,0));
 select e.payload into prior from public.care_events e where e.owner=new.owner and e.kind='care_followup' and e.payload->>'caseId'=case_id order by (e.payload->>'revision')::integer desc limit 1;
 if prior is null then
  if revision<>1 or p->>'status' is distinct from 'open' then raise invalid_parameter_value using message='A case starts open at revision one';end if;
 else
  if revision<>(prior->>'revision')::integer+1 then raise unique_violation using message='Care case revision changed';end if;
  if prior->>'status' in ('resolved','cancelled') then raise invalid_parameter_value using message='A closed case requires a new follow-up';end if;
  if (p-array['status','note','revision','actor','updatedAt','contactChannel','contactResult','escalationTarget','outcome','assignedToName','escalationTargetName']) is distinct from (prior-array['status','note','revision','actor','updatedAt','contactChannel','contactResult','escalationTarget','outcome','assignedToName','escalationTargetName']) then raise invalid_parameter_value using message='Case identity is immutable';end if;
  if coalesce(p->>'status','') not in ('contact_attempted','contact_confirmed','escalated','resolved','cancelled') then raise invalid_parameter_value;end if;
 end if;
 if p ? 'contactChannel' and coalesce(p->>'contactChannel','') not in ('phone','sms','in_app','in_person') then raise invalid_parameter_value;end if;
 if p ? 'contactResult' and coalesce(p->>'contactResult','') not in ('reached','no_answer','failed') then raise invalid_parameter_value;end if;
 if p->>'status' in ('contact_attempted','contact_confirmed') and (not p ? 'contactChannel' or not p ? 'contactResult') then raise invalid_parameter_value;end if;
 if p->>'status'='contact_confirmed' and p->>'contactResult' is distinct from 'reached' then raise invalid_parameter_value;end if;
 if p->>'status'='contact_attempted' and p->>'contactResult'='reached' then raise invalid_parameter_value;end if;
 if p->>'status'='escalated' and not private.care_planning_person(p->>'escalationTarget',city,'leader') then raise invalid_parameter_value;end if;
 if p->>'status'='resolved' and coalesce(length(btrim(p->>'outcome')),0) not between 5 and 1600 then raise invalid_parameter_value;end if;
 return new;
end $$;
revoke all on function private.care_operations_guard() from public,anon,authenticated;
create trigger care_operations_guard before insert or update or delete on public.care_events for each row execute function private.care_operations_guard();
create unique index care_followup_revision on public.care_events(owner,(payload->>'caseId'),((payload->>'revision')::integer)) where kind='care_followup';
create unique index care_assignment_revision on public.care_events(owner,(payload->>'city'),((payload->>'revision')::integer)) where kind='care_assignment' and payload->>'entryType'='assignment';
